import{g9 as o,g8 as a,ga as s,g7 as n}from"./index-CT-h-X-A.js";import{S as e}from"./shared-Crjz4w_p.js";const r={"canto-n1-l01":o(s("n1-l01","teoria"),a("Para cantar, tu cuerpo es tu instrumento. Ponte de pie con los pies separados al ancho de la cadera, rodillas sueltas (no trabadas), espalda larga y hombros relajados.","La cabeza va derecha, sin estirar el cuello hacia adelante ni levantar la barbilla. La mandíbula, suelta.","Antes de cantar, relaja: gira los hombros hacia atrás, mueve suavemente el cuello de lado a lado y bosteza para soltar la garganta.","> Imagina que un hilo te jala suavemente desde la coronilla hacia el techo."),s("n1-l01","lectura"),a("La altura nos dice si un sonido es agudo (como un silbido) o grave (como un tambor grande). Al cantar, tu voz puede subir y bajar de altura.","Las notas graves se sienten más en el pecho y las agudas más en la cabeza.",'> Haz una "sirena" suave con la boca cerrada (mmm), de grave a agudo y de regreso.')),"canto-n1-l02":o(a("La voz se produce así: el aire sale de los pulmones, pasa por la laringe y hace vibrar los pliegues vocales (también llamados cuerdas vocales). Esa vibración se amplifica en la garganta, la boca y la nariz (los resonadores).","Los labios, la lengua y los dientes le dan forma al sonido para que se convierta en palabras.",'> Pon tu mano en tu garganta y di "aaa": esa vibración es tu voz.'),a("Al inhalar, el diafragma (un músculo debajo de los pulmones) baja y deja espacio para que entre el aire. Por eso, al respirar bien, se expanden el abdomen y las costillas bajas, no los hombros.",'Ejercicio: pon una mano en tu abdomen, inhala por la nariz en 4 tiempos sintiendo cómo se expande, sostén 4 tiempos y exhala en 8 tiempos con un "sss".',"> Si los hombros suben al inhalar, vuelve a intentarlo más despacio."),s("n1-l02","lectura"),s("n1-l02","oido")),"canto-n1-l03":o(a('Todo sonido tiene cuatro propiedades: altura (agudo o grave), duración (largo o corto), intensidad (fuerte o suave) y timbre (el "color" que hace que cada voz sea única).',"Al cantar controlas las cuatro: qué nota cantas, cuánto la sostienes, con cuánta fuerza y con qué color de voz.","> Canta la misma nota suave y luego fuerte, sin gritar."),a('Para cantar frases largas necesitas soltar el aire de forma pareja. Ejercicio: inhala y exhala con "sss" lo más parejo y largo que puedas, sin empujar.','Luego cambia a "fff" y después a una nota cómoda con "uuu", tratando de que el sonido no tiemble ni se apague antes de tiempo.',"> Lleva la cuenta de cuántos segundos aguantas: verás cómo mejoras semana a semana."),s("n1-l05","lectura"),a('La intensidad es qué tan fuerte o suave suena algo. En música se le llama dinámica: "piano" (p) es suave y "forte" (f) es fuerte.',"Cantar fuerte no es gritar: el volumen sale del apoyo del aire, no de apretar la garganta.","> Escucha una canción y fíjate en qué partes se canta suave y en cuáles fuerte.")),"canto-n1-l04":o(a("Cuida tu voz: toma agua a lo largo del día, duerme bien y evita gritar o hablar muy fuerte por mucho tiempo.","Calienta antes de cantar y no cantes si te duele la garganta. Si la ronquera o la molestia no se quitan después de varios días, avisa a tu familia y a tu maestro para consultar a un médico.","> El cansancio vocal es una señal: descansa la voz."),a("Una rutina de calentamiento corta (5 a 10 minutos):",'1) Estiramientos suaves de cuello y hombros. 2) Respiración 4-4-8. 3) Vibración de labios ("brrr") en sirenas suaves. 4) "Mmm" con la boca cerrada en notas cómodas. 5) Vocalizaciones cortas con "a" y "o".',"> Empieza siempre en tu zona cómoda y sube poco a poco."),a("En clave de Sol: Do va en la primera línea adicional por debajo del pentagrama, Re justo debajo de la 1ª línea y Mi en la 1ª línea.","Las voces más graves suelen cantar estas notas una octava más abajo de como se oyen en el piano; tu maestro te dirá cuál octava es cómoda para ti.","> Canta Do-Re-Mi-Re-Do con la nota de referencia de la app."),a("Escucha una nota del teclado y cántala igual, como si fueras un eco.",'Usa la herramienta "Afinación de voz → Imita la nota" de la app para ver qué tan cerca estás.',"> Primero escucha, luego imagina la nota en tu cabeza y después cántala.")),"canto-n1-l05":o(a('Cantar afinado es producir la misma altura que la nota que se pide. Cuando cantas un poco más agudo se dice que estás "alto" y cuando cantas más grave, "bajo".',"La afinación se entrena: escuchar con atención es tan importante como cantar.","> Grábate y escúchate: es la mejor forma de detectar en qué notas te desafinas."),a('Canta notas largas con "uuu" o "ooo" sobre una nota cómoda, sosteniéndolas 4 a 8 tiempos sin que la altura se mueva.',"Usa el detector de la app: la aguja debe quedarse cerca del centro.","> Si la nota se cae al final, inhala un poco antes de quedarte sin aire."),a("En clave de Sol: Fa va en el 1er espacio y Sol en la 2ª línea (la que rodea la espiral de la clave).","Ya puedes leer cinco notas seguidas: Do, Re, Mi, Fa y Sol.","> Canta Do-Re-Mi-Fa-Sol subiendo y bajando, despacio."),a('Escucha dos versiones de una misma nota: una afinada y otra un poco desafinada. La desafinada suena como si "chocara" o "temblara" con la nota correcta.',"> Haz el ejercicio de afinado o desafinado tantas veces como quieras.")),"canto-n1-l06":o(a("Las cinco vocales (a, e, i, o, u) cambian la forma de tu boca y de tu lengua, y por eso también cambian el color de tu voz.","La resonancia es cómo se amplifica tu voz en la garganta, la boca y la nariz. Una boca con espacio por dentro (como al empezar un bostezo) ayuda a que la voz suene más llena.",'> Canta "mi-me-ma-mo-mu" en una nota y siente cómo cambia la vibración.'),a("Vocaliza en escalas cortas de 5 notas (Do-Re-Mi-Fa-Sol-Fa-Mi-Re-Do) con cada vocal.","Busca que todas las vocales suenen igual de claras y con el mismo volumen.","> Usa un espejo: la mandíbula va relajada y la lengua descansa detrás de los dientes de abajo."),a('La corchea dura medio tiempo: dos corcheas ocupan lo mismo que una negra. Se cuentan "1 y 2 y 3 y 4 y".',"Los silencios también se cuentan: son momentos sin sonido, y muchas veces son el momento perfecto para respirar.","> Marca con una coma (,) en tu partitura los silencios donde vas a respirar."),s("n1-l04","oido")),"canto-n1-l07":o(a("El semitono es la distancia más pequeña entre dos notas (dos teclas vecinas del teclado). El tono equivale a dos semitonos.","Entre las notas naturales hay un tono, excepto entre Mi-Fa y Si-Do, donde hay solo un semitono.","> Do-Re = tono. Mi-Fa = semitono."),a('Canta la escala de Do mayor subiendo y bajando, con "la" o con los nombres de las notas.',"Ten cuidado con los semitonos (Mi-Fa y Si-Do): son pasos más pequeños y es fácil cantarlos demasiado grandes.","> Si el Do agudo no te queda cómodo, cántala en una tonalidad más grave: tu maestro te ayudará."),a("En clave de Sol: La va en el 2º espacio, Si en la 3ª línea (la de en medio) y el Do agudo en el 3er espacio.","Con esto ya puedes leer toda la escala de Do, desde el Do central hasta el Do agudo.","> Señala y canta las notas de la escala en el pentagrama."),a('Un semitono suena muy "pegadito"; un tono suena un poco más abierto.',"> Escucha Mi-Fa y luego Do-Re en el teclado de la app, y compáralos.")),"canto-n1-l08":o(a("La extensión es el total de notas que puedes cantar, de la más grave a la más aguda. La tesitura es la zona donde tu voz suena cómoda y bonita.","Las voces se clasifican de forma aproximada (soprano, mezzosoprano, contralto, tenor, barítono, bajo), pero en esta etapa lo importante es conocer tu zona cómoda. La voz cambia con la edad y con el entrenamiento.",'> No hay voces "mejores" que otras: cada voz tiene su lugar.'),a('Usa la herramienta "Afinación de voz → Mi rango" de la app: canta tu nota grave cómoda y sube poco a poco hasta tu nota aguda cómoda.',"Nunca fuerces para llegar más arriba o más abajo. Anota tus resultados y compártelos con tu maestro.","> Si sientes molestia o la voz rasposa, detente y descansa."),a("En una partitura de canto, la letra va debajo de las notas: cada sílaba corresponde a una nota.","Cuando una sílaba dura varias notas, se escribe con un guion o una línea después de la sílaba.","> Lee primero la letra en ritmo, sin cantar; después agrega las notas."),a("La octava es la misma nota, pero más aguda o más grave. Es común que dos personas canten la misma melodía a una octava de distancia.",'> Escucha un Do grave y un Do agudo en el teclado: suenan "iguales pero en otra altura".')),"canto-n1-l09":o(a("La dicción es pronunciar con claridad para que se entienda la letra. La articulación es el trabajo de labios, lengua, dientes y paladar para formar las consonantes.","Al cantar, las vocales llevan el sonido y las consonantes deben ser rápidas y claras.","> Exagera un poco las consonantes al practicar; después vuelve a lo natural."),a('Di trabalenguas despacio y después más rápido, con la boca bien activa. Por ejemplo: "Tres tristes tigres tragaban trigo en un trigal".',"Luego cántalo en una sola nota, cuidando cada consonante.","> Practica frente a un espejo para ver si tu boca se mueve lo suficiente."),a("En la partitura, la ligadura une notas: si son iguales, se sostiene el sonido; si son diferentes, se cantan en una misma sílaba, sin cortar.","La respiración se suele marcar con una coma (,) o una V arriba del pentagrama.","> Planea tus respiraciones antes de cantar y márcalas con lápiz."),a("Escucha una melodía de 3 notas y trata de cantarla igual. Pregúntate: ¿la segunda nota sube o baja? ¿y la tercera?",'> Cántala primero con "la" y después con los nombres de las notas.')),"canto-n1-l10":o(a("La voz de pecho es la que usas normalmente al hablar: se siente vibrar en el pecho y suena más llena. La voz de cabeza es más ligera y se siente vibrar en la cabeza; se usa para las notas agudas.",'Entre las dos hay una zona de cambio (pasaje) donde la voz puede "quebrarse". Con práctica, el cambio se vuelve más suave.','> Imita el ulular de un búho ("uuu") en agudo: así se siente la voz de cabeza.'),a('Haz sirenas suaves con "uuu" o con vibración de labios, de grave a agudo, buscando pasar de un registro a otro sin cortes.',"Hazlo a volumen medio o suave: el volumen fuerte hace más difícil el cambio.","> Si la voz se quiebra, no pasa nada: es parte del aprendizaje."),a("El sostenido (♯) sube una nota un semitono; el bemol (♭) la baja un semitono. Por ejemplo, Fa♯ es la tecla negra a la derecha de Fa.","Una misma nota puede tener dos nombres: Do♯ y Re♭ suenan igual. En la partitura, una alteración vale para todo el compás."),a("Escucha la misma nota cantada con voz de pecho y con voz de cabeza. La de pecho suena más llena; la de cabeza más ligera y aireada.","> Escucha a tus cantantes favoritos y trata de reconocer cuándo usan cada registro.")),"canto-n1-l11":o(a("Muchas canciones populares tienen estas partes: introducción, verso (la letra cambia), coro (la parte que se repite y se queda en la memoria), y a veces un puente (una parte diferente) y un final.","Conocer la estructura te ayuda a memorizar la canción y a saber cuándo entrar.","> Escribe la estructura de tu canción favorita: intro, verso, coro…"),a("Aprende una canción por secciones: primero el coro (porque se repite), después cada verso y al final las uniones entre partes.","Para cada sección: escucha, di la letra en ritmo, tararea la melodía y después canta.","> Practica las partes difíciles despacio antes de cantar la canción completa."),a('El signo de repetición (dos puntos junto a una barra doble) indica que hay que repetir esa sección. También verás indicaciones como "D.C." (desde el inicio) o "al Coda" (saltar a la sección final, marcada con el signo ⊕).',"> Sigue la partitura con el dedo mientras escuchas la canción."),a("Escucha una canción e identifica cuándo empieza el verso y cuándo el coro. El coro suele tener más energía y repetir la misma letra.","> Levanta la mano cada vez que empiece el coro.")),"canto-n1-l12":o(a("Cantar con pista es como cantar con una banda: la pista no te espera, así que tienes que escuchar y entrar a tiempo.","Escucha la pista varias veces antes de cantar: aprende la introducción, cuántos compases dura y qué instrumento te da la entrada.","> Cuenta los compases de la introducción en voz baja."),a("Canta tu primera canción completa con pista. Calienta antes, ten agua cerca y respira en los lugares que marcaste.","Si te equivocas, no te detengas: sigue la pista y vuelve a entrar en la siguiente frase.","> Grábate y escúchate después con tu maestro."),a("Repaso: lee una melodía de 8 compases con las notas que ya conoces.","Antes de cantar, revisa la clave, el compás y las figuras. Di los nombres de las notas en ritmo y, al final, cántala con la nota de referencia.","> Marca con lápiz las notas que se te dificulten."),a("La introducción de una canción suele durar un número exacto de compases (4 u 8, por ejemplo). Contar te dice exactamente cuándo entrar.",'> Escucha la introducción y di "¡ahora!" justo cuando debería empezar la voz.'))},t={"canto-n3-l01":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["El apoyo es la sensación de sostener el aire de forma controlada mientras cantas: los músculos del abdomen, la cintura y la espalda baja trabajan para que el aire salga parejo, sin empujarlo ni dejarlo escapar de golpe.","No es apretar el abdomen: es mantener la expansión de las costillas el mayor tiempo posible mientras el aire sale."],tips:['Pon las manos en la cintura: al cantar una nota larga, intenta que no se "desinflen" de golpe.']},practica:{paragraphs:['Inhala por la nariz expandiendo cintura y costillas. Canta una nota cómoda en "a" durante 8 tiempos, empezando suave (p) y creciendo hasta mf, sin que la nota cambie de afinación.',"Luego al revés: de mf a p (diminuendo). Repite en 3 notas distintas."],tips:["Si la nota se sube o se baja al crecer, reduce el volumen máximo."]},lectura:{paragraphs:["En una partitura vocal, la respiración se marca con una coma (,) o una V pequeña sobre el pentagrama. Planear dónde respirar evita cortar palabras o quedarte sin aire.","Respira en las comas y puntos de la letra, al final de las frases y en los silencios."],tips:["Marca con lápiz tus respiraciones antes de aprender una canción."]},oido:{paragraphs:["Una nota apoyada suena estable, con brillo y volumen constante. Una nota sin apoyo tiembla, se apaga o suena con aire. Escucha y decide."],tips:["Fíjate en el final de la nota: si se cae, le faltó apoyo."]}}},"canto-n3-l02":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["El rango vocal se amplía poco a poco con ejercicios suaves y frecuentes, nunca forzando. Trabaja primero en la zona cómoda y extiende medio tono a la vez.","Señales para parar: dolor, ardor, ronquera o sensación de apretar la garganta."],tips:["Calienta siempre antes de trabajar notas agudas o graves."]},practica:{paragraphs:['Sirena: desliza la voz de grave a agudo y de vuelta con "u" o con labios vibrando (brrr), sin cortes. Escala de 5 notas (Do–Re–Mi–Fa–Sol–Fa–Mi–Re–Do) en "a" o "i", subiendo medio tono cada vez y bajando al llegar al límite cómodo.'],tips:["Las sirenas con labios relajan la voz: úsalas al inicio y al final."]},lectura:{paragraphs:["Las notas que no caben en el pentagrama se escriben con líneas adicionales. En clave de Sol, el Do central está en la primera línea adicional debajo; La agudo, en la primera línea adicional arriba."],tips:["Cuenta las líneas adicionales desde el pentagrama, de una en una."]},oido:{paragraphs:['El pasaje es la zona donde la voz cambia de registro (de pecho a cabeza). Puede sonar como un "quiebre" o un cambio de color. Escucha y decide dónde ocurre.'],tips:["Escucha una sirena y señala con la mano dónde cambia el sonido."]}}},"canto-n3-l03":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["La voz mixta combina la fuerza de la voz de pecho con la ligereza de la voz de cabeza. Permite cantar notas en la zona del pasaje sin quiebres ni gritos.","Se logra con poco peso, vocales estrechas (u, i) y mucho apoyo, bajando el esfuerzo de la garganta."],tips:['Piensa en "hablar ligero" en el agudo, no en empujar.']},practica:{paragraphs:['Canta una escala de 5 notas en "nei" o "gu", empezando en voz de pecho y subiendo sin cambiar a falsete ni empujar. Si se quiebra, baja el volumen y estrecha la vocal.'],tips:['Los ejercicios con "ng" (como en "tengo") ayudan a encontrar la mezcla.']},lectura:{paragraphs:["Antes de cantar, identifica en la partitura las notas que están en tu pasaje y márcalas. Planea qué vocal y qué volumen usarás en esas notas."],tips:["Practica primero el fragmento del pasaje aislado."]},oido:{paragraphs:["Voz de pecho: plena, como al hablar. Voz de cabeza: ligera, aguda. Mixta: equilibrio entre ambas. Escucha y decide qué registro se usa."],tips:["Pon una mano en el pecho: si vibra fuerte, es voz de pecho."]}}},"canto-n3-l04":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["En un grupo, cada voz debe escuchar a las demás y ajustarse. Afinar no es cantar más fuerte: es igualar la altura con los demás.","Ayuda cantar con volumen moderado, escuchar la nota de referencia y ajustar las vocales para que suenen parecidas."],tips:["Si no te escuchas, canta más suave, no más fuerte."]},practica:{paragraphs:['Un drone es una nota sostenida (por ejemplo, Do en un teclado o una app). Canta sobre él la escala mayor, deteniéndote en cada nota para sentir si "encaja" o si hay batimientos (ondulaciones).'],tips:['Las notas que suenan más "redondas" con el drone son la tónica, la quinta y la octava.']},lectura:{paragraphs:['Unísono: dos voces cantan la misma nota (en partitura, una nota con dos plicas o "unis."). Octava: la misma nota a ocho notas de distancia, como cuando hombres y mujeres cantan juntos.'],tips:["Las voces masculinas suelen cantar la melodía una octava abajo de lo escrito para soprano."]},oido:{paragraphs:['Un grupo afinado suena compacto, como una sola voz. Desafinado suena con ondulaciones o "choques". Escucha y decide.'],tips:['Fíjate si las notas largas "laten".']}}},"canto-n3-l05":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["En un coro se agrupan las voces por cuerdas: soprano (aguda femenina), contralto (grave femenina), tenor (aguda masculina) y bajo (grave masculina). Cada cuerda canta una línea distinta y juntas forman los acordes."],tips:["Pregúntale al profe Luis cuál es tu cuerda según tu rango."]},practica:{paragraphs:["Aprende tu línea por separado, luego cántala mientras alguien (o una grabación) canta la otra voz. Cubre un oído si te pierdes, pero intenta escuchar ambas."],tips:["Empieza con canciones en terceras paralelas."]},lectura:{paragraphs:["En la partitura coral, cada voz tiene su pentagrama (o comparten con plicas hacia arriba y abajo). Las letras S, A, T, B indican la cuerda. La letra va debajo de las notas."],tips:["Sigue tu línea con el dedo mientras escuchas la grabación."]},oido:{paragraphs:["Escucha un coro y distingue: soprano (lo más agudo), contralto (media grave femenina), tenor (aguda masculina) y bajo (lo más grave). Decide qué voz canta la melodía."],tips:["Concéntrate en una voz a la vez."]}}},"canto-n3-l06":{status:"borrador",generated:!0,sections:{teoria:e.s032,practica:{paragraphs:["Canta las escalas con nombres de notas: Sol mayor (Sol–La–Si–Do–Re–Mi–Fa♯–Sol), Re mayor (Re–Mi–Fa♯–Sol–La–Si–Do♯–Re), Fa mayor (Fa–Sol–La–Si♭–Do–Re–Mi–Fa). Usa el piano de la app como referencia."],tips:["Escucha la tónica antes de empezar."]},lectura:e.s033,oido:e.s034}},"canto-n3-l07":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:['La síncopa coloca acentos fuera del pulso, en los contratiempos. En la voz se usa para dar groove, sobre todo en pop, soul y música latina. Cantar sincopado requiere sentir el pulso con el cuerpo mientras la voz entra "entre los golpes".'],tips:["Marca el pulso con el pie y canta la frase sobre él."]},practica:{paragraphs:['Canta frases cortas que empiecen en el "y" del tiempo, por ejemplo "(1) y-2-y" con la letra "va-mos-ya". Usa el metrónomo y luego una pista.'],tips:["Exagera las consonantes para que la síncopa se entienda."]},lectura:{paragraphs:["En la partitura, las síncopas suelen escribirse con ligaduras que cruzan el tiempo o la barra de compás. La nota ligada se sostiene sin volver a atacar la sílaba."],tips:['Cuenta "1-y-2-y" y marca con el lápiz dónde empieza cada sílaba.']},oido:e.s153}},"canto-n3-l08":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["En el ensayo con banda, sostén el micrófono a 2–5 cm de la boca y apúntalo hacia ti, no hacia el monitor. Aleja el micrófono en notas muy fuertes y acércalo en notas suaves.","No cubras la rejilla con la mano: cambia el sonido y causa acoples."],tips:["Pide en el monitor tu voz y un instrumento de referencia (teclado o guitarra)."]},practica:{paragraphs:["Conoce la introducción y cuenta los compases para entrar a tiempo. Acuerda con la banda señales para el final (mirada, gesto). Practica con la pista completa."],tips:["Aprende las últimas notas de la intro: son tu señal de entrada."]},lectura:{paragraphs:["Una hoja de forma resume la canción: Intro (4 compases), Verso 1, Coro, Verso 2, Coro, Puente, Coro x2, Final. Ayuda a no perderse con la banda."],tips:["Ten la hoja de forma a la vista en el ensayo."]},oido:{paragraphs:["Dentro de la banda, tu voz debe oírse clara. Escucha una grabación de ensayo y decide si la voz se entiende o se pierde."],tips:["Si no te escuchas, pide más voz en el monitor; no grites."]}}},"canto-n3-l09":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:['Los coros de apoyo (backing vocals) acompañan a la voz principal: pueden cantar armonías, repetir palabras clave o responder frases ("pregunta y respuesta"). Deben sonar más suaves y unificados que la voz principal.'],tips:["Escucha canciones de soul y góspel: abundan las respuestas del coro."]},practica:{paragraphs:["Canta una armonía una tercera arriba o abajo de la melodía, solo en el coro de la canción, con volumen menor que la voz principal. Igualar vocales y cortes es clave."],tips:["Corta las palabras exactamente al mismo tiempo que la voz principal."]},lectura:{paragraphs:['La segunda voz se escribe en un pentagrama aparte o con plicas hacia abajo. La letra suele ser la misma; a veces solo canta algunas palabras o "uh" y "ah".'],tips:["Practica tu voz sola antes de juntarla."]},oido:{paragraphs:["La primera voz lleva la melodía y la letra completa; el coro de apoyo, armonías o respuestas más suaves. Escucha y decide quién canta qué."],tips:["La primera voz suele estar más al frente en la mezcla."]}}},"canto-n3-l10":{status:"borrador",generated:!0,sections:{teoria:e.s037,practica:{paragraphs:["Frasear con intención es decidir qué quieres expresar en cada frase: ternura, enojo, alegría. Cambia la dinámica, el color y la articulación según esa intención.","Lee la letra en voz alta como si la hablaras y nota qué palabras enfatizas."],tips:["Elige una palabra clave por frase y dale más énfasis."]},lectura:e.s038,oido:{paragraphs:["Escucha una frase cantada y repítela con una variación (otra dinámica, adorno o ritmo). Es la base de la interpretación personal."],tips:["Cambia una sola cosa a la vez."]}}},"canto-n3-l11":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["La voz es un instrumento delicado. Hábitos clave: hidratarte durante el día, dormir bien, evitar gritar y carraspear, no cantar con dolor, descansar la voz después de usarla mucho y calentar/enfriar siempre.","Si la ronquera dura más de dos semanas, consulta a un otorrinolaringólogo o foniatra."],tips:["El reposo vocal no es susurrar: susurrar también cansa la voz."]},practica:{paragraphs:['Calentamiento (10 min): respiración, sirenas con labios, "ng" deslizado, escalas de 5 notas, arpegios suaves. Enfriamiento (3–5 min): sirenas descendentes con labios, suspiros en "u" y bostezos suaves.'],tips:["Enfriar después de cantar es tan importante como calentar antes."]},lectura:{paragraphs:['Una rutina de calentamiento suele estar escrita como pequeños ejercicios con notas, sílabas y la indicación de subir o bajar por semitonos ("subir ½ tono cada vez").'],tips:["Copia tu rutina en una tarjeta y llévala a los ensayos."]},oido:{paragraphs:["La voz cansada suena opaca, con aire o ronca, y le cuestan los agudos. La descansada suena clara y flexible. Escucha y decide."],tips:["Si notas cansancio en tu voz, baja la intensidad o descansa."]}}},"canto-n3-l12":{status:"borrador",generated:!0,sections:{teoria:e.s040,practica:e.s041,lectura:e.s042,oido:e.s043}},"canto-n4-l01":{status:"borrador",generated:!0,sections:{teoria:e.s044,practica:{paragraphs:["Sobre una progresión (C – F – G – C), canta las notas 1-3-5 de cada acorde: Do–Mi–Sol, Fa–La–Do, Sol–Si–Re, Do–Mi–Sol. Así entrenas el oído armónico y aprendes a encontrar armonías."],tips:["Usa el piano de la app para comprobar cada nota."]},lectura:e.s046,oido:e.s047}},"canto-n4-l02":{status:"borrador",generated:!0,sections:{teoria:e.s048,practica:{paragraphs:['Canta una melodía conocida en mayor y luego cambia la tercera (y la sexta) para convertirla en menor. Por ejemplo, "Estrellita" en Do mayor y en Do menor.'],tips:["Nota cómo cambia la emoción."]},lectura:e.s049,oido:e.s050}},"canto-n4-l03":{status:"borrador",generated:!0,sections:{teoria:e.s059,practica:{paragraphs:['Desde una nota (Do), canta: segunda (Do–Re), tercera (Do–Mi), cuarta (Do–Fa) y quinta (Do–Sol). Referencias: 2ª las sílabas "ple-a" de "Cumpleaños feliz"; 3ª inicio de "Oh When the Saints"; 4ª inicio de la "Marcha nupcial" de Wagner ("Aquí viene la novia"); 5ª inicio de "Estrellita".'],tips:["Comprueba cada intervalo con el piano."]},lectura:{paragraphs:["En el pentagrama, una segunda va de línea a espacio vecino; una tercera, de línea a línea (o espacio a espacio); una cuarta salta una línea y un espacio; una quinta, de línea a dos líneas arriba. Se cuentan ambas notas."],tips:["Do–Re = 2ª, Do–Mi = 3ª, Do–Fa = 4ª, Do–Sol = 5ª."]},oido:{paragraphs:["La segunda suena como un paso pequeño; la cuarta, como un salto abierto, como de fanfarria. Escucha y decide."],tips:['Piensa en "ple-a" de "Cumpleaños feliz" (2ª) y "Aquí viene la novia" (4ª).']}}},"canto-n4-l04":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["La balada es una canción lenta y romántica, centrada en la letra y la melodía. En español es un género enorme: José José, Rocío Dúrcal, Luis Miguel, Laura Pausini, y hoy el pop romántico.","Vocalmente pide legato, notas largas bien apoyadas, dinámica (verso íntimo, coro amplio) y una dicción clara."],tips:["Escucha cómo el cantante guarda la potencia para el último coro."]},practica:{paragraphs:["Canta una frase de balada uniendo las notas sin cortes (legato), como si fuera una sola línea. Sostén las notas largas con apoyo y un vibrato suave al final."],tips:["Lleva la consonante final al inicio de la sílaba siguiente para no cortar la línea."]},lectura:{paragraphs:["La hoja de una balada suele mostrar melodía, letra y cifrado. El cifrado ayuda a saber en qué acorde está cada nota y a comunicarte con el acompañante."],tips:["Marca dónde respiras y dónde está el clímax de la canción."]},oido:e.s055}},"canto-n4-l05":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:['El bolero nació en Cuba y se volvió un pilar de la música mexicana con Agustín Lara, Armando Manzanero, Los Panchos y Luis Miguel ("Romance"). Es lento, romántico y elegante.',"Vocalmente pide un fraseo flexible (rubato), voz cálida, dicción cuidada y un uso expresivo del vibrato."],tips:["Escucha a Lucho Gatica y a Eydie Gormé con Los Panchos."]},practica:{paragraphs:['El rubato es "robar" tiempo: alargar algunas notas y acortar otras sin perder el pulso general del acompañamiento. En el bolero, la voz puede atrasarse un poco y alcanzar a la música al final de la frase.'],tips:["Practica primero estrictamente a tiempo; después agrega rubato con cuidado."]},lectura:{paragraphs:["Lee una estrofa de bolero escrita en 4/4: la letra suele colocarse con síncopas y notas que empiezan en contratiempo. Di la letra en ritmo antes de cantarla."],tips:["Aplaude el pulso mientras recitas la letra."]},oido:e.s056}},"canto-n4-l06":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["La ranchera es el género mexicano por excelencia, con mariachi o guitarras. Se canta en ritmos de vals (3/4), polka (2/4) y bolero ranchero. Intérpretes: Lucha Reyes, Lola Beltrán, José Alfredo Jiménez, Vicente Fernández, Ángela Aguilar.","Vocalmente pide voz plena, proyección, notas sostenidas al final y mucha emoción."],tips:['Escucha cómo los cantantes sostienen la nota final de "El Rey".']},practica:{paragraphs:['Canta frases de ranchera con voz plena (sin gritar), apoyo constante y notas finales sostenidas con crescendo. Mantén la garganta relajada y la boca abierta en vocales "a" y "o".'],tips:["Si te duele o raspa, baja la intensidad: la emoción no depende del volumen."]},lectura:{paragraphs:['En 3/4, cada compás tiene tres negras. Las rancheras en vals suelen empezar en anacrusa (antes del primer tiempo fuerte). Lee la letra contando "1-2-3".'],tips:["Marca el tiempo 1 de cada compás."]},oido:e.s057}},"canto-n4-l07":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["El pop busca melodías pegajosas y una voz cercana y clara. El soul (Aretha Franklin, Stevie Wonder, Alicia Keys) usa voz potente, adornos (melismas), ataques expresivos y mucha emoción.","Ambos usan recursos como caídas al final de las notas, voz con aire en los versos y melismas en los coros."],tips:["Escucha cómo los cantantes de soul adornan la última repetición del coro."]},practica:{paragraphs:['Ataque: cómo empieza la nota (suave, con aire o directo). Caída (fall): dejar caer la nota al final. Melisma: varias notas en una misma sílaba. Practica melismas cortos de 3 notas (Sol–Fa–Mi) en "a", lento y afinado.'],tips:["La afinación es más importante que la velocidad en un melisma."]},lectura:{paragraphs:["Un melisma se escribe con varias notas bajo una ligadura y una sola sílaba debajo, seguida de una línea horizontal (extensión) que indica que la sílaba se sostiene."],tips:['Canta primero el melisma en "a" y luego con la sílaba.']},oido:{paragraphs:["Una nota simple sostiene una altura en la sílaba; un melisma recorre varias notas en la misma sílaba. Escucha y decide."],tips:["Cuenta cuántas notas suenan en una misma palabra."]}}},"canto-n4-l08":{status:"borrador",generated:!0,sections:{teoria:e.s063,practica:{paragraphs:["En el verso, canta más íntimo y narrativo; en el coro, más amplio y energético. Cambia la dinámica, el color y la articulación entre secciones."],tips:["Graba la canción completa y verifica que el coro se sienta más grande."]},lectura:e.s065,oido:e.s066}},"canto-n4-l09":{status:"borrador",generated:!0,sections:{teoria:e.s162,practica:{paragraphs:['La anacrusa es una o varias notas antes del primer tiempo fuerte. Muchas canciones empiezan así ("Las Mañanitas", "Cumpleaños feliz"). Cuenta el compás y entra en el tiempo correcto antes del 1.'],tips:['Cuenta "1-2-3-y" y entra en la "y" si la anacrusa es una corchea.']},lectura:e.s164,oido:e.s165}},"canto-n4-l10":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Cantar en otro idioma requiere aprender su pronunciación, su ritmo y el significado de la letra. En inglés, por ejemplo, hay vocales que no existen en español y consonantes finales que se pronuncian.","Entender la letra es esencial para interpretarla con emoción."],tips:["Traduce la letra y escribe la pronunciación de las palabras difíciles."]},practica:{paragraphs:['Trabaja palabra por palabra: escucha al cantante original, repite lento, luego en ritmo. Cuida los finales con consonante (night, love) y vocales como en "cat", "cup" o "bird".'],tips:["Usa diccionarios con audio para comprobar la pronunciación."]},lectura:{paragraphs:['Una letra con pronunciación escribe debajo de cada palabra cómo suena con letras del español (por ejemplo, "love" → "lov"). Ayuda al principio, pero conviene escuchar siempre el original.'],tips:["Marca las sílabas acentuadas en mayúsculas."]},oido:{paragraphs:["Las vocales abiertas (a, o abierta) suenan amplias; las cerradas (i, u), estrechas. Escucha y decide."],tips:["Las vocales cerradas ayudan en el agudo; las abiertas, en el medio."]}}},"canto-n4-l11":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:['La pentatónica mayor (Do–Re–Mi–Sol–La) y la menor (La–Do–Re–Mi–Sol) son ideales para improvisar con la voz. La escala de blues agrega la "blue note": La–Do–Re–Mi♭–Mi–Sol.',"Muchas melodías de pop, soul y góspel usan estas escalas."],tips:['Canta la pentatónica con sílabas como "du" o "ba".']},practica:{paragraphs:['Sobre una pista en La menor, canta frases cortas de 3 a 5 notas con la pentatónica menor, usando sílabas ("du-ba-da"). Deja silencios entre frases y termina en La.'],tips:["Imita primero una frase del profe y luego cámbiala."]},lectura:{paragraphs:['En el pentagrama, la pentatónica se ve como una escala con dos "saltos" de tercera menor (Mi–Sol y La–Do en la pentatónica mayor de Do).'],tips:["Lee la escala y nombra las notas antes de cantarla."]},oido:e.s176}},"canto-n4-l12":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Para aprender un estilo: escucha mucho a sus intérpretes clave, imita frases, identifica sus rasgos (timbre, adornos, ritmo, pronunciación), aprende canciones representativas y luego crea tu propia versión."],tips:["Haz una lista de 5 canciones y 3 cantantes del estilo que elijas."]},practica:{paragraphs:["Elige un estilo (pop, rock, ranchera, bolero, soul…) y practica sus rasgos: tipo de voz, adornos, ataques y finales de nota. Graba una frase imitando al intérprete y otra con tu estilo."],tips:["Imitar es aprender; tu voz propia aparece después."]},lectura:{paragraphs:["Busca la partitura o la hoja de acordes de una canción del estilo elegido. Identifica la forma, el rango, los adornos y las respiraciones."],tips:["Compara la partitura con la grabación: muchos adornos no están escritos."]},oido:{paragraphs:["Escucha una canción e identifica rasgos del estilo: timbre, adornos, ritmo, instrumentación. ¿A qué estilo pertenece?"],tips:["Haz una lista de lo que escuchas antes de responder."]}}},"canto-n5-l01":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Los agudos y graves extremos deben trabajarse con cuidado: calentamiento completo, poco volumen al inicio, vocales estrechas en el agudo y relajación en el grave. Nunca fuerces una nota que no sale."],tips:["Trabaja los extremos al final del calentamiento, no al inicio."]},practica:{paragraphs:['Agudos: sirenas en "u" y escalas de 5 notas subiendo medio tono, sin empujar. Graves: escalas descendentes suaves, sin presionar la laringe hacia abajo. Detente ante cualquier molestia.'],tips:["Medio tono más cada semana es un gran progreso."]},lectura:e.s177,oido:e.s082}},"canto-n5-l02":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["La agilidad es la capacidad de cantar notas rápidas con afinación y claridad. Se desarrolla con escalas y arpegios rápidos, empezando lento y aumentando la velocidad."],tips:["Una voz ágil es ligera: reduce el volumen para ganar velocidad."]},practica:{paragraphs:['Canta escalas de 5 y 9 notas y arpegios (Do–Mi–Sol–Do–Sol–Mi–Do) en "a", con metrónomo. Empieza a 60 BPM en corcheas y sube poco a poco.'],tips:["Marca ligeramente cada nota con el diafragma, sin golpes de garganta."]},lectura:e.s084,oido:e.s085}},"canto-n5-l03":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["El vibrato es una oscilación natural y regular de la altura de la nota. Aparece cuando la voz está libre y apoyada. Un buen vibrato es regular, ni muy ancho ni muy rápido.","Se puede controlar: iniciar la nota recta y luego dejar que aparezca."],tips:["El vibrato no se fuerza moviendo la mandíbula o el abdomen."]},practica:{paragraphs:["Canta una nota larga recta (sin vibrato) durante 4 tiempos y luego deja que aparezca el vibrato otros 4. Después al revés."],tips:["Si no aparece, relaja la garganta y apoya más; no lo fabriques."]},lectura:{paragraphs:['En partituras vocales aparecen indicaciones como "senza vibrato" (sin vibrato), "dolce" (dulce), "espressivo" o la línea ondulada sobre la nota que pide vibrato.'],tips:["Lee todas las indicaciones antes de cantar."]},oido:{paragraphs:["El vibrato ancho oscila mucho en altura; el estrecho, poco. Escucha y decide."],tips:["Un vibrato equilibrado se oye natural, no como un temblor."]}}},"canto-n5-l04":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:['El color (timbre) de la voz puede cambiar: aireado (con aire, íntimo), brillante (con mucho "frente", proyectado) y oscuro (redondo, cálido). Se logra cambiando el espacio de la boca, la posición de la lengua y la cantidad de aire.'],tips:["Usa el color según la emoción de la canción."]},practica:{paragraphs:["Canta una frase tres veces: aireada (deja escapar aire, suave), brillante (sonríe un poco, vocal hacia el frente) y oscura (boca más alta por dentro, como bostezo leve)."],tips:["No uses voz aireada todo el tiempo: cansa la voz."]},lectura:{paragraphs:["Las indicaciones de carácter dicen cómo debe sonar la música: dolce (dulce), con fuoco (con fuego), cantabile (cantado), misterioso, energico."],tips:["Escribe en tu partitura qué color de voz usarás en cada sección."]},oido:{paragraphs:["Escucha una voz y decide si suena aireada, brillante u oscura."],tips:["Fíjate en cuánto aire y cuánto brillo tiene."]}}},"canto-n5-l05":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["A tres voces, cada cantante hace una nota del acorde: por ejemplo, sobre Do mayor, una voz canta Do, otra Mi y otra Sol. Las voces se mueven por pasos cortos para que suene fluido."],tips:["Practica primero cada voz sola con el piano."]},practica:{paragraphs:["Sobre una melodía, canta una tercera arriba (sumando dos notas de la escala) o una quinta (sumando cuatro). Por ejemplo, si la melodía es Do–Re–Mi, la tercera arriba es Mi–Fa–Sol."],tips:["Graba la melodía y canta encima la armonía."]},lectura:{paragraphs:["En una partitura de tres voces, cada una tiene su pentagrama o comparten pentagramas con plicas distintas. Ubica tu voz y sigue las entradas de las demás."],tips:["Marca tu línea con color."]},oido:{paragraphs:["Escucha un acorde cantado y distingue la voz más aguda, la media y la grave. Canta cada una."],tips:["Empieza por la voz más aguda."]}}},"canto-n5-l06":{status:"borrador",generated:!0,sections:{teoria:e.s075,practica:{paragraphs:["El modo dórico es como la escala menor pero con la sexta mayor (Re dórico: Re–Mi–Fa–Sol–La–Si–Do). El mixolidio es como la mayor con la séptima menor (Sol mixolidio: Sol–La–Si–Do–Re–Mi–Fa). Canta cada modo sobre una pista en su tonalidad."],tips:["El dórico suena menor pero luminoso; el mixolidio, mayor con aire de rock o blues."]},lectura:e.s077,oido:e.s078}},"canto-n5-l07":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Una buena letra tiene un tema claro, imágenes concretas y una frase central que se repite en el coro. Las estrofas cuentan la historia; el coro resume la emoción."],tips:["Escribe primero la frase del coro y luego las estrofas."]},practica:{paragraphs:["La métrica es el número de sílabas de cada verso; la rima, la coincidencia de sonidos al final. Escribe una estrofa de 4 versos de 8 sílabas con rima en los versos 2 y 4."],tips:["Cuenta sílabas en voz alta aplaudiendo cada una."]},lectura:{paragraphs:["Al escribir una letra para una melodía, marca las sílabas acentuadas de cada palabra. Deben coincidir con los tiempos fuertes de la música."],tips:["Subraya las sílabas acentuadas en tu letra."]},oido:{paragraphs:['Si la sílaba acentuada de una palabra cae en un tiempo débil, suena raro ("can-CIÓN" cantado como "CAN-ción"). Escucha y decide si coinciden.'],tips:["Di la palabra hablada y compárala con la cantada."]}}},"canto-n5-l08":{status:"borrador",generated:!0,sections:{teoria:e.s090,practica:{paragraphs:["Sobre C – Am – F – G, improvisa una melodía cantando notas de cada acorde en los tiempos fuertes y notas de paso entre ellas. Graba varias versiones y elige la mejor."],tips:["Una melodía con un motivo que se repite es más fácil de recordar."]},lectura:e.s092,oido:e.s093}},"canto-n5-l09":{status:"borrador",generated:!0,sections:{teoria:e.s079,practica:{paragraphs:["Canta los arpegios de acordes con séptima: Cmaj7 (Do–Mi–Sol–Si), Dm7 (Re–Fa–La–Do), G7 (Sol–Si–Re–Fa). Usa el piano de la app como guía."],tips:["La séptima de G7 (Fa) suele resolver al Mi de Do."]},lectura:e.s003,oido:e.s171}},"canto-n5-l10":{status:"borrador",generated:!0,sections:{teoria:e.s086,practica:{paragraphs:["Sobre Dm7 – G7 – Cmaj7, canta una melodía que use la tercera y la séptima de cada acorde: Fa–Do, Si–Fa, Mi–Si. Luego improvisa conectándolas."],tips:["Escucha un estándar de jazz y canta la melodía sobre su II–V–I."]},lectura:e.s087,oido:e.s088}},"canto-n5-l11":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Cantar en escena es comunicar: la mirada, el gesto y el movimiento deben acompañar el mensaje de la canción. Un movimiento natural y con intención conecta más que muchos movimientos sin sentido."],tips:["Ensaya frente a un espejo o grábate en video."]},practica:{paragraphs:["Elige tres puntos del público para mirar, planea un movimiento para el coro y practica la canción completa de pie, con micrófono (o un objeto similar)."],tips:["Respira antes de empezar y sonríe: el público siente tu energía."]},lectura:{paragraphs:["Las indicaciones de expresión en una partitura (dolce, con brio, rit., a tempo, rubato) guían la interpretación. En canciones populares se anotan a mano en la letra."],tips:["Anota en tu letra dónde quieres crecer, suavizar o detenerte."]},oido:{paragraphs:["Escucha una interpretación y decide qué emoción transmite: tristeza, alegría, ternura, fuerza."],tips:["Fíjate en la dinámica, el color de la voz y el tempo."]}}},"canto-n5-l12":{status:"borrador",generated:!0,sections:{teoria:e.s094,practica:{paragraphs:["Graba una maqueta de 1 minuto: primero el acompañamiento (instrumento o pista) y luego la voz con audífonos. Usa el celular o un DAW."],tips:["Terminar es más importante que la perfección."]},lectura:e.s095,oido:e.s096}},"canto-n6-l01":{status:"borrador",generated:!0,sections:{teoria:e.s097,practica:{paragraphs:["Antes de empezar el proyecto final, repasa lo más importante del curso en la voz: técnica, acordes, escalas, ritmos y las canciones que ya sabes. Detecta qué te cuesta y dedica tiempo extra a eso.","Arma una rutina de 20 minutos: 5 de calentamiento, 10 de técnica y 5 de una canción."],tips:["Haz una lista de los temas que dominas y los que necesitas reforzar."]},lectura:e.s098,oido:e.s099}},"canto-n6-l02":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Para grabar voz en casa necesitas un micrófono (de condensador para estudio o dinámico para cuartos ruidosos), una interfaz de audio, audífonos cerrados y un filtro antipop. La interfaz convierte la señal del micrófono en audio digital."],tips:["Graba en el cuarto con más muebles y cortinas: hay menos eco."]},practica:{paragraphs:["Coloca el micrófono a 15–20 cm de la boca con el filtro antipop, ajusta la ganancia para que los picos queden cerca de −10 dB y graba con audífonos. Haz varias tomas."],tips:["Hidrátate y calienta antes de grabar."]},lectura:e.s100,oido:e.s101}},"canto-n6-l03":{status:"borrador",generated:!0,sections:{teoria:e.s102,practica:e.s103,lectura:e.s104,oido:e.s105}},"canto-n6-l04":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Un doble es la misma voz grabada dos veces, que da cuerpo. Los coros son armonías o respuestas. Se colocan con menos volumen que la voz principal y paneados a los lados."],tips:["Usa dobles solo en las partes que necesitan fuerza (por ejemplo, el coro)."]},practica:{paragraphs:["Graba la voz principal completa, luego un doble del coro y dos armonías (una tercera arriba y otra abajo). Panea los dobles y las armonías a los lados."],tips:["Corta las consonantes finales al mismo tiempo en todas las capas."]},lectura:e.s106,oido:e.s107}},"canto-n6-l05":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Pasos básicos: ajusta el volumen para que la voz esté al frente, ecualiza (quita graves innecesarios con un filtro de paso alto ~80–100 Hz), comprime suavemente para igualar el volumen y agrega reverb o delay con moderación."],tips:["Escucha la voz con la mezcla completa, no sola."]},practica:{paragraphs:["Practica en tu DAW: ajusta el volumen de la voz, aplica un filtro de paso alto, un poco de compresión y una reverb corta. Compara antes y después."],tips:["Si la voz suena lejana, baja la reverb."]},lectura:e.s110,oido:e.s111}},"canto-n6-l06":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Define el tema, la estructura y el estilo de tu canción final. Escribe primero la frase central del coro, luego la melodía y después las estrofas."],tips:["Graba ideas en el celular en cuanto aparezcan."]},practica:{paragraphs:["Completa la letra (verso, coro, puente) y la melodía de tu canción. Revisa que las sílabas acentuadas coincidan con los tiempos fuertes y que el rango sea cómodo."],tips:["Canta la canción completa en voz alta varias veces y ajusta lo que no fluya."]},lectura:e.s114,oido:e.s115}},"canto-n6-l07":{status:"borrador",generated:!0,sections:{teoria:e.s116,practica:{paragraphs:["Graba las voces de tu proyecto final: voz principal, dobles y coros. Cuida la posición del micrófono y la ganancia, y elige las mejores tomas."],tips:["Graba las voces cuando tu voz esté descansada."]},lectura:e.s117,oido:{paragraphs:["La voz debe escucharse clara sobre la pista. Escucha y decide si el balance es correcto."],tips:["Prueba la mezcla en audífonos y en la bocina del celular."]}}},"canto-n6-l08":{status:"borrador",generated:!0,sections:{teoria:e.s118,practica:e.s119,lectura:e.s120,oido:e.s121}},"canto-n6-l09":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Para cantar en vivo: ensaya con la banda o la pista, conoce la forma de memoria, prepara tu calentamiento, hidrátate, descansa la voz el día anterior y llega temprano a la prueba de sonido."],tips:["Los nervios son normales: respira lento antes de salir."]},practica:{paragraphs:["Canta tu repertorio completo de pie, con micrófono y como si hubiera público. Grábate en video y revisa afinación, energía y conexión."],tips:["Ensaya también qué harás si te equivocas: seguir siempre adelante."]},lectura:e.s124,oido:{paragraphs:["Mientras cantas, escucha a la banda: el ritmo de la batería, los acordes y las señales para entradas y finales. Escucha una grabación y decide si la voz va junto con la banda."],tips:["Si te pierdes, escucha el bombo y la caja."]}}},"canto-n6-l10":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["En vivo se usa un micrófono dinámico (como el clásico SM58) a pocos centímetros de la boca. El monitor (o in-ear) te permite escucharte: pide tu voz y la referencia que necesites (teclado, guitarra).","Nunca apuntes el micrófono hacia el monitor: produce acoples (chillidos)."],tips:["En la prueba de sonido, canta con el volumen real que usarás en el concierto."]},practica:e.s126,lectura:e.s127,oido:e.s128}},"canto-n6-l11":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["En temporada de presentaciones: duerme bien, hidrátate, evita gritar, hablar mucho en lugares ruidosos y el exceso de alcohol o cafeína. Calienta y enfría en cada presentación y reserva días de descanso vocal."],tips:["Si sientes dolor o ronquera persistente, consulta a un especialista antes de seguir cantando."]},practica:{paragraphs:["Antes: 10 minutos de calentamiento (respiración, sirenas, escalas). Después: 3–5 minutos de enfriamiento (sirenas descendentes, suspiros, silencio vocal un rato)."],tips:["Lleva agua a temperatura ambiente a cada presentación."]},lectura:{paragraphs:["Un plan de práctica organiza tu semana: calentamiento, técnica, repertorio y descanso. Revisa tu plan, marca lo que cumpliste y ajusta lo que falte."],tips:["Practicar poco todos los días es mejor que mucho un solo día."]},oido:{paragraphs:["Escucha una voz y detecta señales de cansancio: ronquera, aire, dificultad en los agudos, afinación inestable."],tips:["Si notas estas señales en ti, descansa la voz."]}}},"canto-n6-l12":{status:"borrador",generated:!0,sections:{teoria:e.s129,practica:{paragraphs:["Repasa las técnicas principales del curso en la voz, del nivel 1 al 6, con metrónomo. Detecta las que ya dominas y las que necesitas seguir practicando.","Organiza una rutina de mantenimiento para después del curso: técnica, repertorio y creación."],tips:["Grábate tocando una pieza de cada nivel: verás todo lo que has avanzado."]},lectura:e.s130,oido:e.s131}}},i={"canto-n2-l01":n(a("Un intervalo es la distancia entre dos notas. Se cuenta incluyendo las dos: de Do a Mi hay una 3ª (Do-Re-Mi) y de Do a Sol una 5ª (Do-Re-Mi-Fa-Sol).","La 3ª mayor mide 2 tonos (Do–Mi) y la 3ª menor, tono y medio (La–Do). La 5ª justa mide 3 tonos y medio (Do–Sol). Son los saltos que más vas a cantar porque forman los acordes.","@listen 3ª mayor (Do–Mi)|c/4 e/4","@listen 3ª menor (La–Do)|a/3 c/4","@listen 5ª justa (Do–Sol)|c/4 g/4","> Para recordarlos: muchas melodías conocidas empiezan con una 5ª o una 3ª. Busca una que te guste y canta solo sus dos primeras notas."),a("Canta en «la»: Do–Mi–Do, Do–Sol–Do y después Do–Mi–Sol–Mi–Do. Primero escucha cada salto, luego imagínalo en silencio y al final cántalo.","Repite empezando medio tono más arriba cada vez, solo mientras te sientas cómoda o cómodo. El salto debe llegar limpio, sin «resbalar» hacia la nota.","@staff treble 4/4 c/4:q e/4:q c/4:q g/4:q|Saltos de 3ª y 5ª","> Si llegas abajo de la nota, piensa la nota de arriba antes de abrir la boca."),a("En el pentagrama, una 3ª se ve como dos notas en líneas seguidas (o en espacios seguidos). Una 5ª salta dos líneas o dos espacios: de línea a línea o de espacio a espacio, dejando uno en medio.","Reconocer la forma del salto te deja cantar sin contar nota por nota.","@staff treble 4/4 e/4:h g/4:h|3ª: de línea a línea vecina","> Con lápiz, escribe «3» o «5» arriba de cada salto de tu canción."),a("Escucha dos notas y decide si es una 3ª o una 5ª. La 3ª suena cercana y «dulce»; la 5ª suena más abierta y hueca, como un llamado.","@listen ¿3ª o 5ª? Primero esta…|c/4 e/4","@listen …y luego esta|c/4 g/4","> Canta las dos notas en voz baja después de oírlas: tu voz te ayuda a medir el salto.")),"canto-n2-l02":n(a("Una escala mayor sigue el patrón tono–tono–semitono–tono–tono–tono–semitono (Do–Re–Mi–Fa–Sol–La–Si–Do). Suena luminosa.","La escala menor natural sigue tono–semitono–tono–tono–semitono–tono–tono (La–Si–Do–Re–Mi–Fa–Sol–La). Suena más seria o melancólica. La diferencia que más se nota es la 3ª: mayor en la primera, menor en la segunda.","@staff treble 4/4 c/4:8 d/4:8 e/4:8 f/4:8 g/4:8 a/4:8 b/4:8 c/5:8|Do mayor","@staff treble 4/4 a/3:8 b/3:8 c/4:8 d/4:8 e/4:8 f/4:8 g/4:8 a/4:8|La menor natural","> Do mayor y La menor usan las mismas notas: por eso se llaman relativas."),a("Vocaliza 1-2-3-4-5-4-3-2-1 en mayor y luego en menor con la misma nota de inicio (por ejemplo Re mayor y Re menor). Usa «mi-me-ma-mo-mu» en cada nota.","Escucha la escala de referencia antes de cada repetición y mantén el mismo apoyo al subir y al bajar.","@listen 5 notas en mayor|d/4 e/4 f#/4 g/4 a/4 g/4 f#/4 e/4 d/4","@listen 5 notas en menor|d/4 e/4 f/4 g/4 a/4 g/4 f/4 e/4 d/4","> Bajar también requiere aire: no dejes que la nota final se apague."),a("La armadura son los sostenidos o bemoles que van al principio de cada línea y valen para toda la canción. Sol mayor lleva un sostenido (Fa♯) y Fa mayor un bemol (Si♭).","Así no tienes que escribir el sostenido o bemol en cada nota: lo recuerdas al ver la armadura.","@staff treble 4/4 g/4:8 a/4:8 b/4:8 c/5:8 d/5:8 e/5:8 f#/5:8 g/5:8|Sol mayor (Fa♯)","> Antes de cantar, mira la armadura y di en voz alta qué nota cambia."),a("Escucha una escala y decide si es mayor o menor. Pon atención en la tercera nota: en mayor queda «arriba» y brillante, en menor queda «abajo» y más oscura.","@listen Escala A|c/4 d/4 e/4 f/4 g/4","@listen Escala B|c/4 d/4 eb/4 f/4 g/4","> Canta solo las tres primeras notas: así se descubre más rápido.")),"canto-n2-l03":n(a("Un acorde son tres o más notas que suenan juntas. El acorde básico (tríada) se forma con la nota que le da nombre, su 3ª y su 5ª: Do mayor = Do–Mi–Sol; La menor = La–Do–Mi.","En cifrado americano: C = Do mayor, Am = La menor, G7 = Sol con séptima. Aunque no toques un instrumento, el cantante necesita saber qué acorde suena para afinar contra él.","@listen Do mayor (C)|c/4+e/4+g/4","@listen La menor (Am)|a/3+c/4+e/4","> Letras: C Do · D Re · E Mi · F Fa · G Sol · A La · B Si."),a("Canta las notas de un acorde una por una (arpegio): 1–3–5–3–1. Primero sobre Do mayor, luego sobre La menor y Fa mayor.","Escucha el acorde completo, canta su nota más grave y después sube. Si las tres notas encajan con el acorde, estás afinando contra la armonía.","@staff treble 4/4 c/4:q e/4:q g/4:q e/4:q|Arpegio de Do mayor","@play 70 4|C Am F G|Canta 1-3-5 sobre cada acorde","> Este ejercicio es la base para cantar segundas voces más adelante."),a("En los cancioneros, los acordes van arriba de la letra, justo sobre la sílaba donde cambian. Para un cantante sirven como mapa: te dicen dónde va el cambio de color y te ayudan a no perder tu lugar.",`                G7         C
Ay, ay, ay, ay, canta y no llores,
                   G7
porque cantando se alegran,
                   C
cielito lindo, los corazones.`,"Así se ve el coro de «Cielito lindo» (Quirino Mendoza, 1882, de dominio público) con cifrado: el G7 llega en «canta» y el C resuelve en «llores».","> Marca con color la sílaba donde cambia cada acorde."),a("Escucha un acorde y decide si es mayor (brillante, estable) o menor (más triste o íntimo).","@listen Acorde 1|g/3+b/3+d/4","@listen Acorde 2|e/3+g/3+b/3","> Si dudas, canta la nota del medio: en el menor está medio tono más abajo.")),"canto-n2-l04":n(a("La tonalidad es la nota «casa» de la canción y su escala. Si una canción está en Do mayor, todo gira alrededor de Do.","Elegir el tono es elegir en qué altura la cantas. El tono correcto es el que deja la nota más aguda y la más grave dentro de tu rango cómodo, no el de la grabación original.","> Un tono más arriba o más abajo no cambia la canción, solo la acomoda a tu voz."),a("Busca la nota más aguda y la más grave de una canción. Cántala en el tono original y después dos semitonos más abajo (o más arriba). Compara cuál se siente más libre.","Grábate en las dos versiones. Elige la que suene mejor sin apretar el cuello, no la que te deje «lucirte» en una nota.","@listen Do mayor|c/4 e/4 g/4 c/5","@listen La misma idea, un tono abajo (Si♭)|bb/3 d/4 f/4 bb/4","> Avísale a tu maestro el tono que elegiste para que acompañe en ese tono."),a("Una partitura guía (lead sheet) tiene la melodía en el pentagrama, la letra abajo y los acordes arriba. Es lo que usan los músicos para tocar contigo.","Fíjate primero en la armadura, el compás y la primera nota. Después sigue la melodía con la letra.","@staff treble 4/4 e/4:q e/4:q f/4:q g/4:q|Melodía guía (con letra abajo y acordes arriba)","> Lleva tu partitura guía al ensayo con el tono anotado arriba."),a("La tónica es la nota donde la melodía «descansa». Escucha el final de una canción y canta la nota en la que termina: casi siempre es la tónica.","@listen Esta frase termina en casa|e/4 d/4 c/4","> Tararea la última nota de varias canciones y compárala con el teclado de la app.")),"canto-n2-l05":n(a("La dinámica es el volumen con el que cantas. Cambiarlo es una de las formas más fuertes de expresar: un verso suave y un coro con más energía cuentan una historia.","Cantar fuerte no es gritar. El volumen sale del apoyo del aire y de la resonancia, no de apretar la garganta.","> Más aire no siempre es más volumen: más resonancia sí."),a("Canta una nota cómoda en «a» durante 8 tiempos: empieza suave (p), crece hasta medio fuerte (mf) y regresa a suave. La afinación no debe moverse.","Después canta una frase de tu canción tres veces: suave, media y fuerte. Fíjate en que el cuello siga relajado en las tres.","@rhythm 4/4 w w|8 tiempos: p → mf → p","> Si sientes raspado o cosquilleo, baja el volumen y vuelve a apoyar."),a("Los matices se escriben debajo del pentagrama: pp (muy suave), p (suave), mp (medio suave), mf (medio fuerte), f (fuerte) y ff (muy fuerte).","El crescendo (< o «cresc.») indica ir subiendo el volumen; el diminuendo (> o «dim.») ir bajándolo.","> Subraya los matices de tu canción antes de ensayarla."),a("Escucha una frase cantada dos veces y decide si la segunda fue más fuerte, más suave o igual.","También escucha dónde crece la música en tus canciones favoritas: casi siempre al llegar al coro.","> Pon atención al final de las frases: muchas veces bajan de volumen.")),"canto-n2-l06":n(a("Una frase musical es como una oración: tiene un inicio, una dirección y un final. Cantarla con sentido es saber hacia qué palabra va y dónde termina.","La respiración se planea según las frases: se respira al terminar una idea, no a la mitad de una palabra.","> Lee la letra en voz alta como si la dijeras: donde haces pausa, probablemente va una respiración."),a("Toma tu canción y marca con una coma (,) dónde vas a respirar. Hay respiraciones largas (entre frases) y cortas (rápidas, por la boca, cuando no hay tiempo).","Canta la canción respetando solo tus marcas. Si te quedas sin aire, mueve la respiración antes, no después.","> Respira un momento antes de la frase, no justo en el tiempo en que empieza."),a("En la partitura, una ligadura de expresión (una curva sobre varias notas) indica que se cantan unidas, en una sola respiración. La coma o una «V» pequeña arriba del pentagrama marca la respiración.","@staff treble 4/4 c/4:q d/4:q e/4:q g/4:q|Una frase que se canta de un solo aire","> Si una frase con ligadura es muy larga para ti, coméntalo con tu maestro: hay trucos para dividirla."),a("Muchas melodías funcionan como pregunta y respuesta: una frase queda «abierta» (como si preguntara) y la siguiente la cierra.","@listen Pregunta (queda abierta)|c/4 d/4 e/4 g/4","@listen Respuesta (cierra en casa)|g/4 e/4 d/4 c/4","> Escucha si la frase te deja esperando algo o te deja tranquila o tranquilo.")),"canto-n2-l07":n(a("El vibrato es una ondulación pequeña y regular de la afinación al sostener una nota. Aparece solo cuando la voz está libre y bien apoyada; no se fabrica moviendo la mandíbula ni el abdomen.","Primero se aprende a sostener la nota recta y estable. El vibrato natural llega con el tiempo y la relajación.","> Una nota recta y afinada siempre es mejor que un vibrato forzado."),a("Sostén una nota cómoda en «u» durante 8 tiempos con el apoyo de la cintura y las costillas. Al final, suelta un poco la presión sin bajar el volumen y observa si aparece una ondulación suave.","Repite en «o» y en «a». Si la voz tiembla de forma irregular, regresa a notas rectas más cortas.","@staff treble 4/4 e/4:w|Nota larga de 4 tiempos (dos veces)","> Las manos en la cintura te avisan si te «desinflas» de golpe."),a("La semicorchea dura la mitad de una corchea: caben cuatro en un tiempo («1-e-y-a»). La síncopa es un acento fuera del tiempo fuerte, muy común en la música popular.","En canto aparecen en frases rápidas con muchas sílabas y en palabras que «se adelantan» al tiempo.","@rhythm 4/4 16 16 16 16 q 8 q 8|Semicorcheas y una síncopa","> Di el ritmo con «ta» antes de ponerle letra."),a("Escucha una nota recta y otra con vibrato. La recta queda fija; la del vibrato ondula de forma pareja, como una ola pequeña.","> Busca en tus canciones favoritas dónde la voz usa vibrato: normalmente al final de las frases largas.")),"canto-n2-l08":n(a("Los adornos son notas extra que decoran la melodía: la apoyatura (una nota vecina antes de la principal), el mordente (la nota, su vecina y de regreso) y los melismas (varias notas en una misma sílaba).","Cada estilo usa adornos distintos: el bolero y la ranchera tienen los suyos, el pop y el soul los suyos. El adorno sirve a la canción, no al revés.","> Primero canta la melodía limpia; el adorno se agrega después."),a("Toma una frase sencilla de tu canción y agrega un solo adorno al final: una apoyatura desde la nota de arriba o un melisma de tres notas.","Hazlo lento, como si cada nota fuera importante, y luego a tempo.","@listen Sin adorno|g/4 e/4","@listen Con apoyatura|a/4 g/4 e/4","> Un adorno bien hecho suena fácil. Si suena trabado, simplifícalo."),a("En la partitura, los adornos se escriben con notas pequeñas antes de la nota principal o con símbolos arriba del pentagrama (por ejemplo, el mordente). En la música popular muchas veces no se escriben: se aprenden de oído.","> Escribe a lápiz tus adornos para recordarlos en el ensayo."),a("Escucha la misma frase dos veces: una original y otra adornada. Di en qué palabra apareció el adorno.","> Cuenta cuántas notas se cantaron sobre esa sílaba.")),"canto-n2-l09":n(a("La armonía vocal es cantar una melodía distinta al mismo tiempo que otra voz. La segunda voz más usada va una 3ª arriba o abajo de la melodía principal.","Para mantenerla, tienes que escuchar las dos voces a la vez y no dejarte llevar por la principal.","@listen Melodía sola|c/4 d/4 e/4 d/4 c/4","@listen Con segunda voz en 3ª arriba|c/4+e/4 d/4+f/4 e/4+g/4 d/4+f/4 c/4+e/4","> Cantar segundas es un entrenamiento de oído excelente."),a("Aprende la segunda voz sola hasta que te salga sin pensar. Después cántala mientras suena la melodía (en la app o con alguien).","Si te «jala» la melodía principal, tápate un oído suavemente para escucharte mejor y vuelve a intentarlo.","@staff treble 4/4 e/4:q f/4:q g/4:q f/4:q|Segunda voz (3ª arriba)","> Empieza con frases de cinco notas antes de pasar a una canción."),a("Cuando hay dos voces en un mismo pentagrama, la de arriba lleva las plicas hacia arriba y la de abajo hacia abajo. También se pueden escribir en dos pentagramas, uno para cada voz.","> Sigue tu voz con el dedo y escucha la otra como acompañamiento."),a("Escucha un fragmento a dos voces y canta la voz de arriba; después, la de abajo.","> La voz principal suele ser la que recuerdas de la canción; la otra «rellena».")),"canto-n2-l10":n(a("El micrófono capta tu voz y la manda a las bocinas. En vivo se usa casi siempre un micrófono dinámico, que capta lo que tiene enfrente y rechaza lo de atrás.","La distancia cambia el sonido: muy cerca suena más grave y fuerte (efecto de proximidad), lejos suena más delgado y bajo.","> Nunca apuntes el micrófono hacia una bocina: provoca acople (ese chillido agudo)."),a("Sostén el micrófono por el cuerpo, no por la rejilla, a unos 3 a 5 cm de la boca y apuntando a ella. En las notas fuertes, aléjalo un poco; en las suaves, acércalo.","Practica una canción con un micrófono (o un cepillo como simulacro) moviendo la distancia según la dinámica.","> Mantén el micrófono en la misma línea de tu boca cuando giras la cabeza."),a("Una lista de canciones (setlist) dice el orden del show, el tono de cada canción, quién empieza y cómo entra la voz: después de 4 compases de introducción, con el piano, a capela, etcétera.","Escribe la tuya con esos datos para que la banda o la pista y tú estén de acuerdo.","> Pon el tono junto al título: «Cielito lindo – Re»."),a("El monitor es la bocina que apunta hacia ti para que te escuches. Si no te oyes, tiendes a gritar; si te oyes demasiado, cantas muy suave.","Pide al técnico más o menos voz en tu monitor antes de empezar.","> Si no te escuchas, tápate un oído un momento para comprobar tu afinación.")),"canto-n2-l11":n(a("Interpretar es contar la historia de la letra. Antes de cantar, pregúntate: ¿quién habla?, ¿a quién?, ¿qué siente?, ¿qué cambia del principio al final?","La técnica te da control; la interpretación hace que el público te crea.","> Una palabra importante por frase: esa es la que se canta con más intención."),a("Di la letra de tu canción como si se la contaras a alguien, sin melodía. Luego cántala manteniendo esa intención. Agrega gestos naturales que acompañen lo que dices, sin exagerar.","Practica frente a un espejo o grábate en video para ver si tu cara y tu cuerpo dicen lo mismo que la letra.","> Mira a un punto fijo del público o de la cámara: conecta mejor que mirar al piso."),a("Las indicaciones de expresión se escriben arriba del pentagrama, casi siempre en italiano: dolce (dulce), con fuoco (con fuego), rubato (con libertad en el tiempo), a tempo (regresar al tempo).","> Escribe al lado de cada sección una palabra en español que describa cómo cantarla."),a("Escucha dos interpretaciones de la misma canción y describe la emoción de cada una: ¿alegre, triste, enojada, tierna? ¿Qué hizo la voz para transmitirla (volumen, color, tiempo)?","> Fíjate en los silencios: también interpretan.")),"canto-n2-l12":n(a("Sentir nervios antes de cantar es normal: el cuerpo se prepara para algo importante. Para la voz, los nervios se notan en la respiración (se acorta) y en el cuello (se tensa).","Lo que más ayuda es estar bien preparado: cantar las canciones completas muchas veces, sin detenerte, como si fuera el día del recital.","> Antes de salir: tres respiraciones lentas de 4 tiempos para inhalar y 8 para exhalar."),a("Ensaya el recital completo, de pie, con el micrófono y en el orden de tu lista. Si te equivocas, sigue cantando: en vivo la música no se detiene.","Incluye el calentamiento antes, agua a la mano y cómo vas a saludar y presentar cada canción.","> Haz al menos un ensayo frente a alguien de confianza."),a("Repaso de lectura del nivel: intervalos de 3ª y 5ª, armaduras de Sol y Fa, cifrado de acordes, matices, ligaduras, respiraciones y signos de adorno.","Lee tu partitura guía de principio a fin diciendo en voz alta: tono, compás, matiz y dónde respiras.","> Lo que no recuerdes, márcalo con color y pregúntalo en clase."),a("Sacar una melodía de oído: escucha una frase corta, cántala, y busca la primera nota con el teclado de la app. Después decide si cada nota siguiente sube, baja o se repite.","@listen Frase para sacar de oído|e/4 g/4 a/4 g/4 e/4 d/4 c/4","> Empieza con frases de 3 a 5 notas y ve alargándolas."))},u={...r,...t,...i};export{u as CONTENT};
